			/**
			 * 해당 Item ID로 탭 아이템을 선택합니다.
			 * @param {Number} pnTabItemId 
			 */
			function selectTabItem(pnTabItemId){
			    
			    var vcTabCont = app.lookup("tabContents");
			    var voUpdItem = vcTabCont.getTabItemByID(pnTabItemId);
			    
			    if(ValueUtil.isNull(voUpdItem)) return;
			    
			    // 선택된 탭에 따라 플로팅 시킬 버튼 그룹을 변경한다.
			    if(pnTabItemId == 1){
			        // 상세정보 버튼 그룹       
			        app.lookup("appheader").floatBoxIds = "grpDtlFltBtns";
			    } else {
			        // 수정 버튼 그룹       
			        app.lookup("appheader").floatBoxIds = "grpUpdFltBtns";
			    }
			    
			    vcTabCont.setSelectedTabItem(voUpdItem);    
			}

			/**
			 * 기타전문기관 선택 셋팅
			 */
			function setEtcSpcltyInstSelNm(){
			    var vsDsEtcSpcltyInstList = app.lookup("dsEtcSpcltyInstList");
			   
			    var instSeNmTxt = "";
			    var instSeNmCnt = 0;
			    
			    vsDsEtcSpcltyInstList.getRowDataRanged().forEach(function(spcltyInst, idx) {
			        var instSe      = spcltyInst.INST_SE;
			        var instNm      = spcltyInst.INST_NM;        
			                
			        if (app.lookup("dsList").getValue(0, instSe) == "Y") {
			            instSeNmCnt++;            
			            if (instSeNmTxt == null || instSeNmTxt == "") {
			                // 기타전문기관기타인 경우 기타 전문 기관명 셋팅
			                if (instSe == "ETC_SPCLTY_INST_ETC_YN") {
			                    instSeNmTxt = app.lookup("dsList").getValue(0, "ETC_SPCLTY_INST_NM");
			                }else{
			                    instSeNmTxt = instNm;    
			                }                
			            }
			        }               
			    });
			    
			    // 1건 이상 선택 한 경우
			    if (instSeNmCnt > 1) {
			        instSeNmTxt = instSeNmTxt + "외 " + (instSeNmCnt-1)  + "건"
			    }
			    
			    app.lookup("txa2").value = instSeNmTxt;
			}

